"""Durable job runner backed by :class:`SQLiteJobStore`."""

from __future__ import annotations

import time
from collections.abc import Callable, Mapping
from typing import Any

from .models import Job, JobState
from .sqlite_store import SQLiteJobStore


class DurableJobRunner:
    """Runs jobs from a :class:`SQLiteJobStore`.

    ``clock`` and ``sleep`` are injectable for deterministic tests. ``clock``
    returns the current numeric timestamp; ``sleep`` pauses execution for the
    given number of seconds.
    """

    def __init__(
        self,
        store: SQLiteJobStore,
        handlers: Mapping[str, Callable[[dict[str, Any]], Any]],
        clock: Callable[[], float] = time.time,
        sleep: Callable[[float], None] = time.sleep,
        backoff_base: float = 1.0,
    ) -> None:
        self.store = store
        self.handlers = handlers
        self.clock = clock
        self.sleep = sleep
        self.backoff_base = backoff_base

    def _backoff(self, attempts: int) -> float:
        return self.backoff_base * (2 ** (attempts - 1))

    def run_next(self) -> Job | None:
        now = self.clock()
        job = self.store.claim_next(now=now)
        if job is None:
            return None
        handler = self.handlers.get(job.kind)
        if handler is None:
            try:
                raise KeyError(f"unknown job kind: {job.kind}")
            except KeyError as exc:
                return self._handle_failure(job, exc)
        try:
            result = handler(job.payload)
        except Exception as exc:
            return self._handle_failure(job, exc)
        return self.store.complete(job.id, result)

    def _handle_failure(self, job: Job, exc: Exception) -> Job:
        error = str(exc)
        if job.attempts >= job.max_attempts:
            return self.store.fail(job.id, error)
        retry_at = self.clock() + self._backoff(job.attempts)
        return self.store.fail(job.id, error, retry_at=retry_at)

    def run_until_idle(self, max_jobs: int | None = None) -> list[Job]:
        """Run eligible jobs until none remain eligible *now*.

        Does not sleep for future-retry eligibility: a job whose retry is not
        yet due is skipped, and the loop ends as soon as no immediately
        eligible job remains.
        """
        self.store.recover_running()
        processed: list[Job] = []
        while max_jobs is None or len(processed) < max_jobs:
            job = self.run_next()
            if job is None:
                break
            processed.append(job)
        return processed

