"""Command line demonstration for the in-memory and durable runners."""

from __future__ import annotations

import argparse
import json
import sys
from typing import Any, Sequence

from .durable_runner import DurableJobRunner
from .memory_store import MemoryJobStore
from .models import JobState
from .runner import JobRunner
from .sqlite_store import SQLiteJobStore


def _echo(payload: dict[str, Any]) -> Any:
    return payload.get("value")


def _sum(payload: dict[str, Any]) -> int | float:
    return sum(payload["numbers"])


BUILTIN_HANDLERS = {"echo": _echo, "sum": _sum}


def _job_to_json(job: dict[str, Any]) -> str:
    return json.dumps(job)


def _durable_job_json(job: Any) -> str:
    return json.dumps(
        {
            "id": job.id,
            "kind": job.kind,
            "state": job.state.value if hasattr(job.state, "value") else job.state,
            "attempts": job.attempts,
            "max_attempts": job.max_attempts,
            "result": job.result,
            "error": job.error,
            "available_at": job.available_at,
        }
    )


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="python -m jobboard.cli",
        description="Run small jobs in memory or durably with SQLite.",
    )
    sub = parser.add_subparsers(dest="command")

    # Legacy single-command form (backward compatible).
    legacy = sub.add_parser(
        "legacy", help="Run a single in-memory job (original behavior)"
    )
    legacy.add_argument("kind", choices=("echo", "sum"))
    legacy.add_argument("payload")

    # Durable subcommands.
    p_enqueue = sub.add_parser("enqueue", help="Enqueue a durable job")
    p_enqueue.add_argument("--db", required=True, dest="db")
    p_enqueue.add_argument("kind")
    p_enqueue.add_argument("payload")
    p_enqueue.add_argument("--max-attempts", type=int, default=3, dest="max_attempts")
    p_enqueue.add_argument("--job-id", default=None, dest="job_id")

    p_work = sub.add_parser("work", help="Process durable jobs until idle")
    p_work.add_argument("--db", required=True, dest="db")
    p_work.add_argument("--max-jobs", type=int, default=None, dest="max_jobs")

    p_status = sub.add_parser("status", help="List durable jobs")
    p_status.add_argument("--db", required=True, dest="db")
    p_status.add_argument("--state", default=None, dest="state")

    p_cancel = sub.add_parser("cancel", help="Cancel a durable job")
    p_cancel.add_argument("--db", required=True, dest="db")
    p_cancel.add_argument("job_id")

    return parser


def _run_legacy(args: argparse.Namespace) -> int:
    try:
        payload = json.loads(args.payload)
    except json.JSONDecodeError as exc:
        print(f"error: invalid JSON payload: {exc}", file=sys.stderr)
        return 2
    store = MemoryJobStore()
    job = store.enqueue(args.kind, payload)
    JobRunner(store, BUILTIN_HANDLERS).run_next()
    print(json.dumps({"id": job.id, "state": job.state.value, "result": job.result}))
    return 0


def _parse_payload(text: str) -> dict[str, Any]:
    try:
        value = json.loads(text)
    except json.JSONDecodeError as exc:
        raise ValueError(f"invalid JSON payload: {exc}") from exc
    if not isinstance(value, dict):
        raise ValueError("payload must be a JSON object")
    return value


def _normalize_state(value: str | None) -> JobState | None:
    if value is None:
        return None
    try:
        return JobState(value)
    except ValueError as exc:
        raise ValueError(
            f"invalid state '{value}'. Expected one of: "
            + ", ".join(s.value for s in JobState)
        ) from exc


def _cmd_enqueue(args: argparse.Namespace) -> int:
    try:
        payload = _parse_payload(args.payload)
    except ValueError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2
    store = SQLiteJobStore(args.db)
    try:
        job = store.enqueue(
            args.kind,
            payload,
            max_attempts=args.max_attempts,
            job_id=args.job_id,
        )
    finally:
        store.close()
    print(_job_to_json({"id": job.id, "state": job.state.value}))
    return 0


def _cmd_work(args: argparse.Namespace) -> int:
    store = SQLiteJobStore(args.db)
    try:
        runner = DurableJobRunner(store, BUILTIN_HANDLERS)
        jobs = runner.run_until_idle(max_jobs=args.max_jobs)
    finally:
        store.close()
    for job in jobs:
        print(_durable_job_json(job))
    return 0


def _cmd_status(args: argparse.Namespace) -> int:
    try:
        state = _normalize_state(args.state)
    except ValueError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2
    store = SQLiteJobStore(args.db)
    try:
        jobs = store.list(state=state)
    finally:
        store.close()
    for job in jobs:
        print(
            _job_to_json(
                {
                    "id": job.id,
                    "kind": job.kind,
                    "state": job.state.value,
                    "attempts": job.attempts,
                    "max_attempts": job.max_attempts,
                    "result": job.result,
                    "error": job.error,
                }
            )
        )
    return 0


def _cmd_cancel(args: argparse.Namespace) -> int:
    store = SQLiteJobStore(args.db)
    try:
        cancelled = store.cancel(args.job_id)
    finally:
        store.close()
    if not cancelled:
        print(f"error: no queued or running job with id {args.job_id}", file=sys.stderr)
        return 1
    print(_job_to_json({"id": args.job_id, "state": "cancelled"}))
    return 0


def main(argv: Sequence[str] | None = None) -> int:
    parser = _build_parser()
    args = parser.parse_args(argv)

    if args.command is None:
        # Backward-compatible legacy form: kind + payload as positional args.
        parser_legacy = argparse.ArgumentParser()
        parser_legacy.add_argument("kind", choices=("echo", "sum"))
        parser_legacy.add_argument("payload")
        legacy_args = parser_legacy.parse_args(argv)
        return _run_legacy(legacy_args)

    if args.command == "legacy":
        return _run_legacy(args)
    if args.command == "enqueue":
        return _cmd_enqueue(args)
    if args.command == "work":
        return _cmd_work(args)
    if args.command == "status":
        return _cmd_status(args)
    if args.command == "cancel":
        return _cmd_cancel(args)

    parser.print_help(sys.stderr)
    return 2


if __name__ == "__main__":
    raise SystemExit(main())

